function draw() {
    // background gradient
    const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
    bgGrad.addColorStop(0, '#001');
    bgGrad.addColorStop(1, '#000');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // stars
    ctx.fillStyle = '#fff';
    for (const s of stars) {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    }

    // ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x + ship.r, ship.y);
    ctx.lineTo(ship.x - ship.r * 0.5, ship.y - ship.r * 0.86);
    ctx.lineTo(ship.x - ship.r * 0.5, ship.y + ship.r * 0.86);
    ctx.closePath();
    ctx.fill();

    // ores (glowing)
    ctx.fillStyle = '#ff0';
    for (const o of ores) if (!o.collected) {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
      ctx.fill();
    }

    // asteroids (rotating irregular shapes)
    ctx.fillStyle = '#f44';
    for (const a of asteroids) {
      ctx.save();
      ctx.translate(a.x, a.y);
      ctx.rotate(a.angle);
      ctx.beginPath();
      const sides = 7;
      for (let i = 0; i < sides; i++) {
        const theta = (i / sides) * Math.PI * 2;
        const radius = a.r * (0.8 + Math.random() * 0.4);
        ctx.lineTo(Math.cos(theta) * radius, Math.sin(theta) * radius);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);

    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

